components.css:
@font-face {
  font-family: Manrope;
  src: url('/assets/manrope.ttf') format('truetype');
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}
:root {
  color-scheme: light;
  --paper: #faf9f6;
  --ink: #59584f;
  --secondary: #706e65;
  --line: #e4e1da;
  --accent: #8a4b32;
  --font: Manrope, "PingFang SC", "Microsoft YaHei", sans-serif;
}
* { box-sizing: border-box; }
html { background: var(--paper); scrollbar-color: #c4ccc2 var(--paper); }
body { margin: 0; color: var(--ink); font-family: var(--font); font-size: 14px; -webkit-font-smoothing: antialiased; }
::selection { background: #e9d9ca; color: #503422; }
a { color: inherit; text-decoration: none; text-underline-offset: 5px; }
button { font: inherit; }
a:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 7px; border-radius: 3px; }
.page { max-width: 792px; margin: 0 auto; padding: 0 36px; }
.header { display: flex; align-items: center; justify-content: space-between; padding-top: 48px; }
.wordmark { font-size: 18px; font-weight: 400; letter-spacing: -.025em; }
.name-dot { color: var(--secondary); }
.languages { display: flex; align-items: center; gap: 12px; }
.languages button { appearance: none; border: 0; background: none; padding: 8px 2px; color: var(--secondary); font-size: 11px; cursor: pointer; min-height: 36px; }
.languages button[aria-pressed="true"] { color: var(--ink); }
.languages button:hover { color: var(--accent); }
.language-divider { height: 11px; width: 1px; background: #cdd3cb; }
.intro { display: grid; grid-template-columns: minmax(0, 1fr) 228px; gap: 48px; align-items: center; padding: 72px 0 64px; }
h1 { font-size: 21px; font-weight: 400; line-height: 1.6; letter-spacing: -.02em; margin: 0; text-wrap: balance; }
.intro-description { font-size: 14px; line-height: 2; color: var(--secondary); margin: 16px 0 0; }
.portrait { margin: 0; }
.portrait img { display: block; width: 100%; height: auto; aspect-ratio: 3 / 4; object-fit: contain; border-radius: 3px; }
.products { scroll-margin-top: 32px; }
.section-heading { padding-bottom: 18px; }
h2 { font-size: 12px; font-weight: 400; margin: 0; color: var(--secondary); }
.product { position: relative; display: grid; grid-template-columns: 34px 1fr 18px; gap: 18px; align-items: start; border-top: 1px solid var(--line); padding: 25px 0; }
.product:last-child { border-bottom: 1px solid var(--line); }
.product-mark { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 10px; margin-top: 2px; }
.product-mark svg { width: 24px; height: 24px; }
.cadence-mark { background: #e7ede3; color: #46653d; }
.listening-mark { background: #ede9e1; color: #846a43; }
.race-mark { background: #e4ebee; color: #4e7080; }
.product-content { display: flex; flex-direction: column; align-items: flex-start; min-width: 0; }
.product-title { font-size: 16px; line-height: 1.5; letter-spacing: -.015em; font-weight: 400; display: flex; gap: 12px; align-items: center; }
.product-category { font-size: 11px; letter-spacing: 0; color: var(--secondary); }
.product-description { color: var(--secondary); font-size: 13px; line-height: 1.85; margin-top: 5px; max-width: 53ch; text-wrap: pretty; }
.product-domain { font-size: 11px; color: var(--secondary); margin-top: 9px; }
.arrow { width: 16px; height: 16px; margin-top: 5px; color: var(--secondary); transition: transform 200ms cubic-bezier(.16,1,.3,1), color 200ms; }
.product:hover .arrow, .product:focus-visible .arrow { transform: translate(2px,-2px); color: var(--accent); }
.product:hover .product-title { color: var(--accent); }
.footer { padding: 26px 0 36px; color: var(--secondary); font-size: 11px; line-height: 1.8; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 600px) {
  .page { padding: 0 24px; }
  .header { padding-top: 26px; }
  .intro { grid-template-columns: 1fr; gap: 28px; padding: 46px 0 44px; }
  h1 { font-size: 20px; }
  .intro-description { font-size: 13px; margin-top: 12px; }
  .portrait { width: 210px; max-width: 100%; }
  .product { gap: 14px; padding: 23px 0; }
  .product-title { font-size: 15px; }
  .product-description { font-size: 12px; }
  .footer { padding: 24px 0 30px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; scroll-behavior: auto !important; }
}
